BasaltExceptionCode code = BasaltExceptionCode.fromCode(-2);
if (code == BasaltExceptionCode.SHAPE_MISMATCH) { System.err.println(code.code() + ": " + code.description());
}

try (Basalt jsl = Basalt.create(4)) { basalt.zeros(4096, 4096);
} catch (BasaltMemoryException failure) { System.err.println(failure.statusCode() + " " + failure.getMessage());
}

try (Basalt jsl = Basalt.create()) { basalt.activation(basalt.nn.Activation.NONE);
} catch (BasaltRuntimeException failure) { System.err.println(failure.getMessage());
}

try { basalt.tensor(new float[]{1f, 2f, 3f}, 2, 2);
} catch (IllegalArgumentException | BasaltShapeException failure) { System.err.println(failure.getMessage());
}

try (Basalt jsl = Basalt.create()) { basalt.activation(basalt.nn.Activation.SOFTMAX);
} catch (BasaltRuntimeException failure) { System.err.println(failure.statusCode());
}

BasaltMetrics.MetricsSnapshot snapshot = BasaltMetrics.snapshot(basalt.context());
String json = snapshot.toJson();
String metrics = snapshot.toPrometheus();

BasaltMetrics.OperatorSummary summary = BasaltMetrics.snapshot(basalt.context()).operators().get("randn");
if (summary != null) { System.out.println(summary.calls() + " calls, p95 = " + summary.p95Micros() + " us");
}
